def _make_tree(root):
    root = str(root)
    os.makedirs(os.path.join(root, "subdir"))
    for name in ("alpha.txt", "beta.py", "gamma.md"):
        with open(os.path.join(root, name), "w") as f:
            f.write("x")
    return root

def test_r13_distinct_predicates_are_all_applied(tmp_path):
    root = _make_tree(tmp_path / "data")
    calls = []

    def pred_a(name):
        calls.append(("a", name))
        return True

    def pred_b(name):
        calls.append(("b", name))
        return False

    result = task_func(root, [pred_a, pred_b])
    assert len(calls) == 8
    assert set(result.keys()) == {"alpha.txt", "beta.py", "gamma.md", "subdir"}

def test_r10_empty_directory_returns_empty_dict(tmp_path):
    empty = tmp_path / "empty"
    empty.mkdir()
    assert task_func(str(empty), [lambda name: True]) == {}

